CREATE TABLE pipeline_runs (id INTEGER PRIMARY KEY AUTOINCREMENT, "run_date" TEXT, "output_dir" TEXT, "genome_ref" TEXT, "genome_size" TEXT, "control" TEXT, "threads" TEXT, "mapq" TEXT, "max_frags" TEXT, "macs3_format" TEXT, "macs3_foldch_levels" TEXT, "macs3_meme_foldch_level" TEXT, "meme_nmotifs" TEXT, "meme_minw" TEXT, "meme_maxw" TEXT, "meme_maxpeaks" TEXT, "fimo_thresh" TEXT, "sample" TEXT, "r1" TEXT, "r2" TEXT, "is_treatment" TEXT, "total_reads" TEXT, "trimmed_reads" TEXT, "mapped_reads" TEXT, "alignment_rate" TEXT, "reads_in_peaks" TEXT, "reads_in_peaks_filt" TEXT, "max_peak_score" TEXT, "mapping_pct" TEXT, "motif_peaks" TEXT, "subsampled_frags" TEXT, "median_frag_size" TEXT, "num_peaks" TEXT, "num_peaks_filt" TEXT);
CREATE TABLE run_metadata (id INTEGER PRIMARY KEY AUTOINCREMENT, "output_dir" TEXT, "sample" TEXT, "author" TEXT, "run_date" TEXT, "experiment_date" TEXT, "gdna_batch" TEXT, "genome_ref" TEXT, "gene_annotation" TEXT, "r1" TEXT, "r2" TEXT, "trimmed_r1" TEXT, "trimmed_r2" TEXT, "bam" TEXT, "bigwig" TEXT, "peaks_narrowpeak" TEXT, "peaks_filt_narrowpeak" TEXT, "summits_bed" TEXT, "summits_fasta" TEXT, "peaks_fasta" TEXT, "meme_summits_dir" TEXT, "meme_peaks_dir" TEXT, "fimo_summits_tsv" TEXT, "fimo_peaks_tsv" TEXT, "homer_annotations" TEXT, "report_csv" TEXT);
